-- Piano Pre Grade: Piano Adventures Level 1 Lesson Book.
-- Renames the existing Methode Book subject when that catalog is already present.
-- A database without PIANO keeps this schema and does not invent a second program.

create table if not exists public.curriculum_lesson_guides (
  item_id uuid primary key references public.curriculum_component_items(id) on delete cascade,
  source_book text not null,
  source_edition text not null,
  source_authors text not null,
  source_pages text not null,
  piece_reference text not null,
  learning_objectives text not null,
  core_concepts text not null,
  teacher_demonstration text not null,
  guided_practice text not null,
  independent_practice text not null,
  review text not null,
  checkpoint text not null,
  homework text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint curriculum_lesson_guides_pages_check check (source_pages ~ '^[0-9]{1,3}(, [0-9]{1,3})?$'),
  constraint curriculum_lesson_guides_objective_check check (learning_objectives like 'Student performs %')
);

create index if not exists curriculum_lesson_guides_pages_idx
  on public.curriculum_lesson_guides (source_pages);

drop trigger if exists trg_curriculum_lesson_guides_updated_at on public.curriculum_lesson_guides;
create trigger trg_curriculum_lesson_guides_updated_at
before update on public.curriculum_lesson_guides
for each row execute function public.set_updated_at();

alter table public.curriculum_lesson_guides enable row level security;
revoke all on public.curriculum_lesson_guides from public, anon, authenticated;
grant select on public.curriculum_lesson_guides to authenticated;
grant all on public.curriculum_lesson_guides to service_role;

drop policy if exists curriculum_lesson_guides_super_admin_read on public.curriculum_lesson_guides;
create policy curriculum_lesson_guides_super_admin_read
on public.curriculum_lesson_guides
for select to authenticated
using (public.has_role('SUPER_ADMIN'));

create or replace function public.session_teaching_academic(p_program uuid) returns jsonb
language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('id',e.id,'name',cur.name,'level_id',e.current_level_id,'level_name',l.name,
  'started_at',lp.started_at,'level_status',lp.status,'subjects',coalesce((
   select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'rule',s.completion_rule,
    'progress_id',sp.id,'status',coalesce(sp.status,'NOT_STARTED'),'components',coalesce((
     select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'rule',c.completion_rule,
      'progress_id',cp.id,'status',coalesce(cp.status,'NOT_STARTED'),'items',coalesce((
       select jsonb_agg(jsonb_build_object('id',i.id,'code',i.code,'name',i.name,'progress_id',ip.id,'status',coalesce(ip.status,'NOT_STARTED')) order by i.sort_order,i.id)
       from curriculum_component_items i left join student_component_item_progress ip on ip.item_id=i.id and ip.component_progress_id=cp.id
       where i.component_id=c.id and i.status='ACTIVE'),'[]'::jsonb)) order by c.sort_order,c.id)
     from curriculum_subject_components c left join student_component_progress cp on cp.component_id=c.id and cp.subject_progress_id=sp.id
     where c.subject_id=s.id and c.status='ACTIVE'),'[]'::jsonb)) order by s.sort_order,s.id)
   from curriculum_subjects s left join student_subject_progress sp on sp.subject_id=s.id and sp.level_progress_id=lp.id
   where s.level_id=e.current_level_id and s.status='ACTIVE'),'[]'::jsonb))
 from student_curriculum_enrollments e join curriculums cur on cur.id=e.curriculum_id
 left join curriculum_levels l on l.id=e.current_level_id
 left join student_level_progress lp on lp.enrollment_id=e.id and lp.level_id=e.current_level_id
 where e.id=p_program and e.status='ACTIVE'
$$;

create or replace function public.academic_video_link_context(p_student uuid, p_enrollment uuid)
returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare can_manage boolean; result jsonb;
begin
  if not public.can_read_academic_video_links(p_enrollment,true)
    or not exists(select 1 from public.student_curriculum_enrollments where id=p_enrollment and student_id=p_student)
  then raise exception using errcode='42501',message='VIDEO_LINK_FORBIDDEN'; end if;
  can_manage := public.has_role('SUPER_ADMIN');
  select jsonb_build_object(
    'can_manage',can_manage,
    'links',coalesce((select jsonb_agg(jsonb_build_object(
      'id',v.id,'title',v.title,'url',v.url,'note',v.note,'level_id',v.level_id,'item_id',v.item_id,
      'level_name',l.name,'lesson_name',concat_ws(' · ',s.name,c.name,i.code,i.name),
      'shared_with_family',v.shared_with_family,'version',v.version
    ) order by v.created_at desc,v.id)
      from public.academic_video_links v
      left join public.curriculum_levels l on l.id=v.level_id
      left join public.curriculum_component_items i on i.id=v.item_id
      left join public.curriculum_subject_components c on c.id=i.component_id
      left join public.curriculum_subjects s on s.id=c.subject_id
      where v.enrollment_id=p_enrollment and v.deleted_at is null
      and public.can_read_academic_video_links(v.enrollment_id,v.shared_with_family)), '[]'::jsonb),
    'levels',case when can_manage then coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'name',l.name) order by l.sequence_no,l.id)
      from public.student_level_progress lp join public.curriculum_levels l on l.id=lp.level_id
      where lp.enrollment_id=p_enrollment), '[]'::jsonb) else '[]'::jsonb end,
    'lessons',case when can_manage then coalesce((select jsonb_agg(jsonb_build_object(
      'id',i.id,'level_id',s.level_id,'name',concat_ws(' · ',i.code,i.name))
      order by l.sequence_no,s.sort_order,c.sort_order,i.sort_order,i.id)
      from public.student_level_progress lp join public.curriculum_levels l on l.id=lp.level_id
      join public.curriculum_subjects s on s.level_id=l.id
      join public.curriculum_subject_components c on c.subject_id=s.id
      join public.curriculum_component_items i on i.component_id=c.id
      where lp.enrollment_id=p_enrollment), '[]'::jsonb) else '[]'::jsonb end
  ) into result;
  return result;
end $$;

